"""
    Computes elementwise mean across arrays.
    E.g. for input [[1, 2, 4], [5, 3, 6]] returns [3, 2.5, 5]
    :param arrays: list of arrays of the same length
    :return: elementwise average across arrays
    """
def mean_across_arrays(arrays: Any) -> object {
    out_arr = [];
    n_arrays = len(arrays);
    for i in range(len(arrays[0])) {
        sm = 0;
        for array in arrays {
            sm += array[i];
        }
        out_arr.append((sm / n_arrays));
    }
    return out_arr;
}

"""Repeatedly apply a function using a regular python loop.

    Args:
        i (int): the current iteration count.
        init_x: The initial values fed to `func`.
        func (callable): The function which is repeatedly called.
        num_iter (int): The number of times to apply the function `func`.
        return_last_two (bool, optional): When `True`, return the two last
            outputs of `func`.

    Returns:
        The last output of `func`, or, if `return_last_two` is `True`, a tuple
        with the last two outputs of `func`.
    """
def unrolled(
    i: Any, init_x: Any, func: Any, num_iter: Any, return_last_two: Any = False
) -> object {
    x = init_x;
    x_old = None;
    for _ in range(num_iter) {
        x_old = x;
        x = func(x_old);
        i = i + 1;
    }
    if return_last_two {
        return (i, x, x_old);
    } else {
        return (i, x);
    }
}

"""Returns a new dictionary containing only the given keys.

    Parameters
    ----------
    d : dict
        The original dictionary.
    keys: list of keys
        The keys to keep.  If a key is not found in the dictionary, it is
        ignored.
    """
def only_keys(d: Any, *keys: Any) -> object {
    result = `dict();
    for key in keys {
        if (key in d) {
            result[key] = d[key];
        }
    }
    return result;
}

